static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        if (dayStep <= 0) {
            throw new IllegalArgumentException("dayStep must be greater than 0");
        }

        int year = (int) (timeBucket / 10000);
        int monthDay = (int) (timeBucket % 10000);
        int day = monthDay % 100;
        int month = monthDay / 100;

        // Calculate the first day of the month
        int firstDayOfMonth = 1;

        // Calculate the base day to align with the dayStep
        int baseDay = firstDayOfMonth + ((day - 1) / dayStep) * dayStep;

        // Ensure the baseDay is within the month
        if (baseDay > getDaysInMonth(year, month)) {
            baseDay = firstDayOfMonth + ((getDaysInMonth(year, month) - 1) / dayStep) * dayStep;
        }

        return year * 10000 + month * 100 + baseDay;
    } catch (Exception e) {
        throw new RuntimeException("Error compressing time bucket", e);
    }
}

private static int getDaysInMonth(int year, int month) {
    switch (month) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            return 31;
        case 4: case 6: case 9: case 11:
            return 30;
        case 2:
            return isLeapYear(year) ? 29 : 28;
        default:
            throw new IllegalArgumentException("Invalid month: " + month);
    }
}

private static boolean isLeapYear(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

static long compressTimeBucket(long timeBucket, int dayStep){
    try {
        if (dayStep <= 0) {
            throw new IllegalArgumentException("dayStep must be a positive integer.");
        }
        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket % 10000) / 100);
        int day = (int) (timeBucket % 100);

        // Calculate the new day by adjusting to the nearest lower dayStep multiple
        int newDay = (day / dayStep) * dayStep + 1;

        // Handle edge case where newDay is greater than the last day of the month
        int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        if (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)) {
            daysInMonth[1] = 29; // Leap year
        }
        if (newDay > daysInMonth[month - 1]) {
            newDay = daysInMonth[month - 1];
        }

        return year * 10000 + month * 100 + newDay;
    } catch (Exception e) {
        // Log exception or handle as needed
        throw new RuntimeException("Error in compressing time bucket", e);
    }
}

