    if (file == null || !file.exists() || !file.isFile()) {
        throw new IllegalArgumentException("File must be a valid existing file");
    }
    if (timeRanges == null) {
        throw new IllegalArgumentException("Time ranges must not be null");
    }

    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            ThreadSnapshot snapshot = parseThreadSnapshot(line);
            if (snapshot != null && isWithinTimeRanges(snapshot.getTimestamp(), timeRanges)) {
                snapshots.add(snapshot);
            }
        }
    }
    return snapshots;
}

