private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    // Check if the descriptor is a method descriptor
    if (descriptor.startsWith("(")) {
        int i = descriptor.indexOf(')');
        if (i == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
        }
        String argumentTypes = descriptor.substring(1, i);
        parseArgumentTypes(argumentTypes);
    } else {
        // Treat the descriptor as a field descriptor
        parseArgumentTypes(descriptor);
    }
}

private void parseArgumentTypes(String argumentTypes) {
    int i = 0;
    while (i < argumentTypes.length()) {
        char c = argumentTypes.charAt(i);
        switch (c) {
            case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                // These are single-slot types
                popOneSlot();
                i++;
                break;
            case 'D': case 'J':
                // These are double-slot types
                popTwoSlots();
                i++;
                break;
            case 'L':
                // Object type
                int endIndex = argumentTypes.indexOf(';', i);
                if (endIndex == -1) {
                    throw new IllegalArgumentException("Invalid object descriptor: " + argumentTypes.substring(i));
                }
                popOneSlot();
                i = endIndex + 1;
                break;
            case '[':
                // Array type
                int dimensions = 0;
                while (i < argumentTypes.length() && argumentTypes.charAt(i) == '[') {
                    dimensions++;
                    i++;
                }
                if (i == argumentTypes.length()) {
                    throw new IllegalArgumentException("Invalid array descriptor: " + argumentTypes);
                }
                char arrayType = argumentTypes.charAt(i);
                if (arrayType == 'L') {
                    int semicolonIndex = argumentTypes.indexOf(';', i);
                    if (semicolonIndex == -1) {
                        throw new IllegalArgumentException("Invalid array descriptor: " + argumentTypes.substring(i));
                    }
                    i = semicolonIndex + 1;
                } else {
                    i++;
                }
                popOneSlot();
                break;
            default:
                throw new IllegalArgumentException("Invalid type character in descriptor: " + c);
        }
    }
}

