private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    int i = 0;
    if (descriptor.charAt(0) == '(') {
        // Method descriptor, extract and pop each argument type
        i++;
        while (descriptor.charAt(i) != ')') {
            switch (descriptor.charAt(i)) {
                case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                    // Each of these occupies one slot
                    popOneSlot();
                    break;
                case 'D': case 'J':
                    // Each of these occupies two slots
                    popTwoSlots();
                    break;
                case '[':
                    // Array type, treat as one slot
                    popOneSlot();
                    break;
                case 'L':
                    // Object type, treat as one slot
                    while (descriptor.charAt(i) != ';') {
                        i++;
                    }
                    popOneSlot();
                    break;
                default:
                    throw new IllegalArgumentException("Invalid descriptor character: " + descriptor.charAt(i));
            }
            i++;
        }
    } else {
        // Type descriptor, pop one or two slots depending on the type
        switch (descriptor.charAt(0)) {
            case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                popOneSlot();
                break;
            case 'D': case 'J':
                popTwoSlots();
                break;
            case '[':
                popOneSlot();
                break;
            case 'L':
                popOneSlot();
                while (descriptor.charAt(i) != ';') {
                    i++;
                }
                break;
            default:
